<?php
namespace App\Jobs;
use App\Events\AutoblogPostUpdated;use App\Models\AutoblogPost;use App\Services\Autoblog\ProviderError;use App\Services\Autoblog\Publisher;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Throwable;
class PublishAutoblogPost implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public int $timeout=120;public array $backoff=[15,60,180];public function __construct(public int $postId){$this->onQueue('autoblog');}public function handle(Publisher $publisher):void{$post=AutoblogPost::withoutGlobalScopes()->with('destination')->findOrFail($this->postId);if($post->status==='published')return;$savedDestination=$post->destination&&$post->destination->is_active;if(!$savedDestination&&blank($post->destination_url)){$post->update(['status'=>'failed','last_error'=>'The publishing destination is missing or inactive.']);$this->announce($post);return;}$post->update(['status'=>'publishing','last_error'=>null]);$this->announce($post);try{$result=$savedDestination?$publisher->publish($post,$post->destination):$publisher->publishToUrl($post,$post->destination_url);$post->update(['status'=>'published','external_id'=>$result['id'],'external_url'=>$result['url'],'published_at'=>now(),'last_error'=>null]);$this->announce($post->fresh());}catch(Throwable $e){$post->update(['status'=>'failed','last_error'=>ProviderError::friendly($e)]);$this->announce($post->fresh());throw $e;}}private function announce($post):void{try{broadcast(new AutoblogPostUpdated($post));}catch(Throwable $e){report($e);}}}
